4.query:
timeseries age = max(cohesity.protectiongroup.last_success.age, scalar:true), by:{cohesity.protectiongroup.id, cohesity.protectiongroup.sla_violated}
| filter cohesity.protectiongroup.sla_violated == "true"
| summarize `Groups in SLA violation` = countDistinctExact(cohesity.protectiongroup.id)

7.query:
timeseries age = max(cohesity.protectiongroup.last_success.age, scalar:true), by:{cohesity.protectiongroup.name}
| fieldsAdd bucket = if(age > 86400000, "over 24h", else: if(age > 43200000, "12-24h", else: if(age > 21600000, "6-12h", else: "under 6h")))
| summarize `Protection groups` = count(), by:{`Time since last success` = bucket}
| sort `Protection groups` desc

14.query:
timeseries { used = avg(cohesity.cluster.capacity.used), total = avg(cohesity.cluster.capacity.total) }
| fieldsAdd `Used %` = arrayLast(used) * 100.0 / arrayLast(total)
| fields `Used %`

15.query:
timeseries { logical = sum(cohesity.cluster.usage.logical), physical = sum(cohesity.cluster.usage.physical) }
| fieldsAdd `Data reduction ratio` = arrayLast(logical) / arrayLast(physical)
| fields `Data reduction ratio`

18.query:
timeseries { used = avg(cohesity.cluster.capacity.used), total = avg(cohesity.cluster.capacity.total) }, by:{cohesity.cluster.name}
| fieldsAdd `Used %` = used[] * 100.0 / total[]
| fields timeframe, interval, cohesity.cluster.name, `Used %`

19.query:
timeseries { logical = avg(cohesity.storagedomain.usage.logical), physical = avg(cohesity.storagedomain.usage.physical) }, by:{cohesity.storagedomain.name}
| fields domain = cohesity.storagedomain.name, logical = arrayLast(logical), physical = arrayLast(physical)
| append [ timeseries resiliency = avg(cohesity.storagedomain.resiliency.bytes), by:{cohesity.storagedomain.name} | fields domain = cohesity.storagedomain.name, resiliency = arrayLast(resiliency) ]
| summarize { Logical = max(logical), Physical = max(physical), `Resiliency overhead` = max(resiliency) }, by:{`Storage domain` = domain}
| fieldsAdd `Reduction ratio` = Logical / Physical
| sort Physical desc, `Resiliency overhead` desc
